# 🤖 RawrXD Full Agentic Test Suite
# Comprehensive testing of all AI/Agent capabilities
# Tests: Chat processing, Agent commands, Model integration, Critical functions

param(
  [Parameter(Mandatory = $false)]
  [string]$TestLevel = "COMPREHENSIVE",

  [Parameter(Mandatory = $false)]
  [switch]$GenerateReport = $true,

  [Parameter(Mandatory = $false)]
  [string]$OutputPath = ".\AGENTIC-TEST-RESULTS.md"
)

# Test configuration
$script:TestResults = @()
$script:TestStartTime = Get-Date
$script:TotalTests = 0
$script:PassedTests = 0
$script:FailedTests = 0
$script:WarningTests = 0
$script:InfoTests = 0

# Function to safely format colors
function Get-SafeColor {
    param([string]$Color)
    $validColors = @("Black", "DarkBlue", "DarkGreen", "DarkCyan", "DarkRed", "DarkMagenta", "DarkYellow", "Gray", "DarkGray", "Blue", "Green", "Cyan", "Red", "Magenta", "Yellow", "White")
    if ($Color -and $Color -in $validColors) {
        return $Color
    }
    return "Gray"
}
$script:TotalTests = 0
$script:PassedTests = 0
$script:FailedTests = 0
$script:WarningTests = 0

# Colors for output
$Red = "Red"
$Green = "Green"
$Yellow = "Yellow"
$Cyan = "Cyan"
$Magenta = "Magenta"

function Write-TestHeader {
  param([string]$Title)
  Write-Host "`n" -NoNewline
  Write-Host "=" * 70 -ForegroundColor Cyan
  Write-Host "🤖 $Title" -ForegroundColor Magenta
  Write-Host "=" * 70 -ForegroundColor Cyan
}

function Write-TestResult {
  param(
    [string]$TestName,
    [string]$Status,
    [string]$Details = "",
    [string]$Category = "GENERAL"
  )

  $script:TotalTests++

  # Normalize status to handle variations
  $normalizedStatus = switch -Wildcard ($Status.ToUpper()) {
    "PASS*" { "PASS" }
    "FAIL*" { "FAIL" }
    "WARN*" { "WARN" }
    "INFO*" { "INFO" }
    default { "INFO" }
  }

  $colorMap = @{
    "PASS" = "Green"
    "FAIL" = "Red"
    "WARN" = "Yellow"
    "INFO" = "Cyan"
  }

  $icon = switch ($normalizedStatus) {
    "PASS" { "✅"; $script:PassedTests++ }
    "FAIL" { "❌"; $script:FailedTests++ }
    "WARN" { "⚠️"; $script:WarningTests++ }
    "INFO" { "ℹ️" }
    default { "❓" }
  }

  $color = $colorMap[$normalizedStatus]
  if (-not $color -or [string]::IsNullOrEmpty($color)) { $color = "Gray" }

  $safeColor = Get-SafeColor $color
  Write-Host "$icon [$Category] $TestName" -ForegroundColor $safeColor
  if ($Details) {
    Write-Host "   └─ $Details" -ForegroundColor Gray
  }

  $script:TestResults += @{
    TestName  = $TestName
    Category  = $Category
    Status    = $normalizedStatus
    Details   = $Details
    Timestamp = Get-Date
  }
}

