      # Test function structure
      $functionStart = $rawrContent.IndexOf($func.Pattern)
      $functionSection = $rawrContent.Substring($functionStart, [Math]::Min(500, $rawrContent.Length - $functionStart))

      if ($functionSection -match "param\s*\(") {
