      $script:totalHiddenFound += $matches.Count

      foreach ($match in $matches) {
        $hiddenFeatures.ExperimentalFeatures += @{
          Type    = $expType
          Content = $match.Value
          Pattern = $pattern
        }
      }
    }
  }
}

