    "Config to UI Integration"   = @{
      Pattern     = "settings.*\.Text|\.Text.*settings|config.*\.Text|\.Text.*config"
      Description = "Configuration connected to UI elements"
      Found       = $false
    }
  }

  foreach ($integration in $integrationTests.Keys) {
