    $modelId = $parts[1]
    $modelSize = $parts[2]
    $modified = ($parts[3..($parts.Count - 1)] -join " ")

    # Convert size to GB for calculation
    $sizeInGB = 0
    if ($modelSize -match "(\d+\.?\d*)\s*GB") {
      $sizeInGB = [float]$matches[1]
      $totalSize += $sizeInGB
    }
    elseif ($modelSize -match "(\d+)\s*MB") {
      $sizeInGB = [float]$matches[1] / 1024
      $totalSize += $sizeInGB
    }

