class SwarmOrchestrator:
    """Main orchestrator managing all swarm agents"""

    def __init__(self):
        self.agents: Dict[str, SwarmAgent] = {}
        self.agent_status: Dict[str, AgentStatus] = {}
        self.task_results: Dict[str, Dict[str, Any]] = {}
        self.task_counter = 0

        # Initialize subsystems
        self.model_manager = ModelManager()
        self.message_broker = MessageBroker()

        # Performance metrics
        self.start_time = time.time()
        self.tasks_processed = 0

    def initialize_agents(self):
        """Initialize all 10 specialized agents"""
        agent_configs = [
            ("ai_processor_1", AgentType.AI_PROCESSOR),
            ("ai_processor_2", AgentType.AI_PROCESSOR),
            ("text_editor_1", AgentType.TEXT_EDITOR),
            ("text_editor_2", AgentType.TEXT_EDITOR),
            ("team_viewer_1", AgentType.TEAM_VIEWER),
            ("marketplace_1", AgentType.MARKETPLACE),
            ("data_sync_1", AgentType.DATA_SYNC),
            ("monitor_1", AgentType.MONITOR),
            ("error_recovery_1", AgentType.ERROR_RECOVERY),
            ("resource_manager_1", AgentType.RESOURCE_MANAGER)
        ]

        for i, (agent_id, agent_type) in enumerate(agent_configs):
            # Create specialized agent
            if agent_type == AgentType.AI_PROCESSOR:
                agent = AIProcessorAgent(agent_id, agent_type, self)
            elif agent_type == AgentType.TEXT_EDITOR:
                agent = TextEditorAgent(agent_id, agent_type, self)
            elif agent_type == AgentType.TEAM_VIEWER:
                agent = TeamViewerAgent(agent_id, agent_type, self)
            elif agent_type == AgentType.MARKETPLACE:
                agent = MarketplaceAgent(agent_id, agent_type, self)
            else:
                agent = SwarmAgent(agent_id, agent_type, self)

            self.agents[agent_id] = agent
            self.agent_status[agent_id] = agent.status

            # Setup communication
            self.message_broker.setup_agent_sockets(agent_id, i)

            logger.info(f"Initialized agent: {agent_id} ({agent_type.value})")

    async def start_swarm(self):
        """Start all agents"""
        logger.info("Starting AI Swarm...")

        # Start all agents concurrently
        tasks = [agent.start() for agent in self.agents.values()]
        await asyncio.gather(*tasks)

    async def submit_task(self, agent_type: AgentType, task_data: Dict[str, Any], priority: int = 1) -> str:
        """Submit task to appropriate agent"""
        self.task_counter += 1
        task_id = f"task_{self.task_counter}_{int(time.time())}"

        task = SwarmTask(task_id, agent_type, task_data, priority)

        # Find available agent of specified type
        target_agent = None
        min_load = float('inf')

        for agent in self.agents.values():
            if agent.agent_type == agent_type:
                load = self.agent_status[agent.agent_id].load_percentage
                if load < min_load:
                    min_load = load
                    target_agent = agent

        if target_agent:
            await target_agent.task_queue.put(task)
            logger.info(f"Submitted task {task_id} to {target_agent.agent_id}")
            return task_id
        else:
            logger.error(f"No available agent for type {agent_type}")
            return ""

    async def receive_task_result(self, task_id: str, agent_id: str, result: Dict[str, Any]):
        """Receive task result from agent"""
        self.task_results[task_id] = {
            "agent_id": agent_id,
            "result": result,
            "completed_at": time.time()
        }
        self.tasks_processed += 1
        logger.info(f"Received result for task {task_id} from {agent_id}")

    def update_agent_status(self, status: AgentStatus):
        """Update agent status"""
        self.agent_status[status.agent_id] = status

    def get_swarm_metrics(self) -> Dict[str, Any]:
        """Get overall swarm performance metrics"""
        uptime = time.time() - self.start_time

        total_tasks = sum(status.tasks_completed for status in self.agent_status.values())
        total_errors = sum(status.errors for status in self.agent_status.values())

        avg_load = sum(status.load_percentage for status in self.agent_status.values()) / len(self.agent_status)

        active_agents = sum(1 for status in self.agent_status.values() if status.status == "active")

        return {
            "uptime": uptime,
            "total_tasks": total_tasks,
            "total_errors": total_errors,
            "average_load": avg_load,
            "active_agents": active_agents,
            "total_agents": len(self.agents),
            "tasks_per_second": total_tasks / uptime if uptime > 0 else 0
        }

    def stop_swarm(self):
        """Stop all agents"""
        logger.info("Stopping AI Swarm...")
        for agent in self.agents.values():
            agent.stop()

