Analyze this Python code and describe what it does:

r"""Simple agent self-healing supervisor.

Reads a JSON config with processes to supervise. Starts a monitored process and
restarts it on failure, with optional backoff and max restart attempts.

Usage:

python tools\self_heal.py --config tools\self_heal_config.json

Config schema (JSON array):
[
  {
    "name": "test_agent",
    "command": ["python", "tests/self_heal_agent.py"],
    "restart_on_crash": true,
    "max_restarts": 5,
    "restart_backoff_secs": 1,
    "health_check": {
      "type": "tcp",  # or "http"
      "host": "127.0.0.1",
      "port": 5000,
      "interval_secs": 3,
      "timeout_secs": 1
    }
  }
]

"""

import argparse
import json
import os
import subprocess
import sys
import threading
import time
from typing import Dict, Any, List


class MonitoredProcess:
    def __init__(self, spec: Dict[str, Any]):
        self.name = spec.get('name')
        self.command = spec.get('command')
        self.restart_on_crash = spec.get('restart_on_crash', True)
        self.max_restarts = spec.get('max_restarts', 0)
        self.restart_backoff_secs = spec.get('restart_backoff_secs', 1)
        self.health_check = spec.get('health_check')
        self._process = None
        self._restarts = 0
        self._stop_event = threading.Event()
        self._monitor_thread = None
        self.logfile = spec.get('logfile', f'build/{self.name}.log')
        # Heartbeat detection
        self.heartbeat_keyword = spec.get('heartbeat_keyword')  # if None, any output counts
        self.heartbeat_interval_secs = spec.get('heartbeat_interval_secs', 5)
        self.last_heartbeat = time.time()
        self._stdout_thread = None

    def start(self):
        open(self.logfile, 'a').close()
        print(f"[self_heal] Starting {self.name}: {self.command}")
        # Use PIPE so we can monitor stdout for heartbeat and copy to logfile
        stdout = subprocess.PIPE
        stderr = subprocess.STDOUT
        self._process = subprocess.Popen(self.command, stdout=stdout, stderr=stderr)
        # Start stdout reader
        self._stdout_thread = threading.Thread(target=self._stdout_reader_loop, daemon=True)
        self._stdout_thread.start()
        self._monitor_thread = threading.Thread(target=self._monitor_loop, daemon=True)
        self._monitor_thread.start()

    def _monitor_loop(self):
        while not self._stop_event.is_set():
            if self._process is None:
                time.sleep(0.5)
                continue
            ret = self._process.poll()
            if ret is None:
                # process still running
                time.sleep(0.5)
                continue
            else:
                print(f"[self_heal] Process {self.name} exited with code {ret}")
                if not self.restart_on_crash:
                    return
                self._restarts += 1
                if self.max_restarts and self._restarts > self.max_restarts:
                    print(f"[self_heal] Max restarts reached for {self.name}. Not restarting.")
                    return
                backoff = self.restart_backoff_secs * self._restarts
                print(f"[self_heal] Restarting {self.name} after {backoff} secs backoff (restart #{self._restarts})")
                time.sleep(backoff)
                try:
                    stdout = open(self.logfile, 'ab')
                    # Restart process with PIPE again
                    self._process = subprocess.Popen(self.command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
                    self._stdout_thread = threading.Thread(target=self._stdout_reader_loop, daemon=True)
                    self._stdout_thread.start()
                except Exception as e:
                    print(f"[self_heal] Error restarting {self.name}: {e}")
                    return

    def stop(self):
        self._stop_event.set()
        if self._process and self._process.poll() is None:
            try:
                self._process.terminate()
                self._process.wait(timeout=3)
            except Exception:
                try:
                    self._process.kill()
                except Exception:
                    pass
        # join stdout reader
        if self._stdout_thread:
            try:
                self._stdout_thread.join(timeout=1)
            except Exception:
                pass

    def _stdout_reader_loop(self):
        # Read stdout, write to log, and update heartbeat
        if not self._process or not self._process.stdout:
            return
        with open(self.logfile, 'ab') as f:
            for raw in iter(self._process.stdout.readline, b''):
                try:
                    f.write(raw)
                    f.flush()
                except Exception:
                    pass
                try:
                    line = raw.decode('utf-8', errors='ignore').strip()
                except Exception:
                    line = ''
                now = time.time()
                # If heartbeat keyword is None, any output updates heartbeat
                if self.heartbeat_keyword is None or (self.heartbeat_keyword and self.heartbeat_keyword in line):
                    self.last_heartbeat = now


class Supervisor:
    def __init__(self, specs: List[Dict[str, Any]]):
        self.specs = specs
        self.processes = [MonitoredProcess(s) for s in specs]
        self._stop_event = threading.Event()

    def start_all(self):
        for p in self.processes:
            p.start()
        # Start health check monitor
        self._health_thread = threading.Thread(target=self._health_monitor_loop, daemon=True)
        self._health_thread.start()

    def stop_all(self):
        for p in self.processes:
            p.stop()
        self._stop_event.set()
        # Wait for health thread to exit
        try:
            self._health_thread.join(timeout=1)
        except Exception:
            pass

    def _health_monitor_loop(self):
        # Periodically check health checks and last_heartbeat
        while not self._stop_event.is_set():
            for p in self.processes:
                if p._stop_event.is_set():
                    continue
                # Check heartbeat staleness
                if p.heartbeat_interval_secs:
                    now = time.time()
                    delta = now - p.last_heartbeat
                    if delta > p.heartbeat_interval_secs * 2:  # allow a factor
                        print(f"[self_heal] Heartbeat stale for {p.name} (delta={delta}s); restarting")
                        try:
                            if p._process and p._process.poll() is None:
                                p._process.terminate()
                        except Exception:
                            pass
                # Check configured health_check (tcp/http)
                if p.health_check:
                    try:
                        hc = p.health_check
                        if hc.get('type') == 'tcp':
                            import socket
                            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                            s.settimeout(hc.get('timeout_secs', 1))
                            try:
                                s.connect((hc.get('host', '127.0.0.1'), hc.get('port')))
                                s.close()
                            except Exception:
                                print(f"[self_heal] Health check failed (tcp) for {p.name}; restarting")
                                try:
                                    if p._process and p._process.poll() is None:
                                        p._process.terminate()
                                except Exception:
                                    pass
                        elif hc.get('type') == 'http':
                            import urllib.request
                            url = f"http://{hc.get('host','127.0.0.1')}:{hc.get('port')}{hc.get('path','/') }"
                            try:
                                with urllib.request.urlopen(url, timeout=hc.get('timeout_secs', 1)) as r:
                                    _ = r.read(1)
                            except Exception:
                                print(f"[self_heal] Health check failed (http) for {p.name}; restarting")
                                try:
                                    if p._process and p._process.poll() is None:
                                        p._process.terminate()
                                except Exception:
                                    pass
                    except Exception as e:
                        print(f"[self_heal] health monitor error for {p.name}: {e}")
            time.sleep(1)


def load_config(path: str) -> List[Dict[str, Any]]:
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--config', default='tools/self_heal_config.json')
    args = parser.parse_args()

    if not os.path.exists(args.config):
        print(f"Config {args.config} not found")
        sys.exit(1)

    specs = load_config(args.config)
    sup = Supervisor(specs)
    try:
        sup.start_all()
        print('[self_heal] Supervisor started. Press Ctrl+C to exit.')
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print('[self_heal] Stopping supervision...')
    finally:
        sup.stop_all()


if __name__ == '__main__':
    main()

