					"command": "sqltools.clearBookmarks",
					"when": "view == sqltoolsViewBookmarksExplorer",
					"group": "navigation@1"
				},
				{
					"command": "sqltools.bookmarkSelection",
					"when": "view == sqltoolsViewBookmarksExplorer",
					"group": "navigation@1"
				},
				{
					"command": "sqltools.clearHistory",
					"when": "view == sqltoolsViewHistoryExplorer",
					"group": "navigation@1"
				}
